/**
 * @param {null|boolean|number|string|Array|Object} object
 * @return {string}
 */
var jsonStringify = function(object) {
    // Wrap a string in double quotes, escaping backslash, quote and common control characters
    // (the problem guarantees alphanumeric strings, so this is extra safety)
    const quote = s => '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')
        .replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t') + '"';

    // null first: typeof null === 'object', so it must not fall into the object branch
    if (object === null) return 'null';
    if (typeof object === 'string') return quote(object);

    // Arrays before generic objects, since arrays are also typeof 'object'
    if (Array.isArray(object)) {
        return '[' + object.map(jsonStringify).join(',') + ']';
    }

    // Plain object: keys in Object.keys() order, each as "key":value
    if (typeof object === 'object') {
        return '{' + Object.keys(object)
            .map(key => quote(key) + ':' + jsonStringify(object[key]))
            .join(',') + '}';
    }

    // number or boolean: their string form is already valid JSON
    return String(object);
};
